document.addEventListener("DOMContentLoaded",()=>{const c=document.querySelectorAll(".card");document.addEventListener("mouseover",e=>{const t=e.target.closest(".card");t&&t.classList.add("is-hovered")});document.addEventListener("mouseout",e=>{const t=e.target.closest(".card");t&&t.classList.remove("is-hovered")});document.querySelectorAll('img[loading="lazy"]').forEach(i=>{i.complete?i.classList.add("is-loaded"):i.addEventListener("load",()=>i.classList.add("is-loaded"),{once:!0})});console.info(`Swift initialized with ${c.length} cards.`)});
